-- A build loads its entries sorted, so of two oversized rows it names the one whose key
-- sorts first — the 2 801-character `a…`, inserted second, as a 2 816-byte row.
-- @setup
CREATE TABLE t (a text);
INSERT INTO t VALUES (''), ('');
-- @test
-- @expect-error: the first oversized key in key order
-- @expect-message
-- @profile-lock
CREATE INDEX t_i ON t (a);
